-- ============================================================
-- 6. TRAZABILIDAD: QRs NO PAGADOS vs PAGO POR OTRO MEDIO
-- ============================================================

SELECT q.solicitud_id,
       q.created_at AS qr_generado,
       q.status AS qr_status,
       q.amount AS qr_monto,
       p.pasarela_pago AS medio_pago_real,
       p.fecha_pago AS fecha_pago_real,
       p.monto_pago_total AS monto_pagado,
       TIMESTAMPDIFF(SECOND, q.created_at, p.fecha_pago) AS segundos_diferencia
FROM bbva_qr_payments q
LEFT JOIN cronograma c ON c.solicitud_id = q.solicitud_id AND c.estado = 'activo'
LEFT JOIN pago p ON p.cronograma_id = c.id AND p.deleted_at IS NULL
    AND p.fecha_pago >= '2026-05-25' AND p.fecha_pago < '2026-06-08'
WHERE q.solicitud_id IN (16210,21765,22152,23427,23727,25077,25939,25993,26238,26276,26299,26406,27514,27707,27777,27789,28710,28966,30111,30720,32136,32169,32397,32399,32412,32438,32493,32502,32530,32620,32713,32742,36149,37246,37333,37520,37547,37641,37662,37675,37793,37800,37945,37987,39734,39907,39927,40003,40164,40168,40204,40232,40281,40293,40338,40951,41909,42086,42484,42888,43190,43264,43320,43415,43696,43710,43806,43990,44056,44130,44139,44237,44581,44669,44762,44913,44980,45014,45081,45123,45239,45344,45369,45371,45372,45548,45550,45557,45668,45780,46310,46363,46387,46417,46749,46870,46981,47036,47133,47287,47365,47491,47496,47624,47756,48136,48163,48706,48782,48796,48892,48932,49025,49027,49054,49079,49087,49090,49397,49472,49550,49740,49914,49932,50084,50114,50133,50412,50557,50843,50895,51020,51185,51351,51383,51384,51395,51571,51589,51610,51611,51612,51613,51633,51638,51677,51686,51742,51766,51858,52011,52103,52239,52256,52367,52381,52496,52511,52522,52589,52596,52632,52643,52687,52752,52794,52801,52855,52898,52949,52951,52966,53031,53081,53109,53123,53129,53141,53203,53212,53270,53276,53282,53288,53339,53431,53526,53738,53745,53836,53856,53858,53930,54212,54230,54237,54254,54400,54478,54594,54599,54729,55025,55072,55117,55143,55149,55155,55247,55290,55362,55367,55414,55461,55462,55493,55547,55551,55578,55595,55649,55808,55839,55966,56047,56085,56178,56325,56336,56461,56545,56605,56794,57278,57367,57476,57529,57641,57653,57774,57874,57896,57949,57969,57973,57984,58001,58026,58148,58203,58220,58356,58359,58384,58424,58465,58516,58518,58644,58647,58659,58663,59154,59224,59305,59306,59341,59555,59711,59801,59885,59936,60045,60061,60062,60088,60250,60279,60412,60467,60621,60826,60877,61036,61047,61158,61171,61172,61176,61203,61259,61260,61305,61350,61370,61374,61535,61566,61619,61629)
